pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter attacker;

    function setUp() public {
        c = new C();
        attacker = new Reverter();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        bool ok;
        vm.prank(address(attacker));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // A withdrawal attempt by a party whose fallback reverts must NOT
        // complete: the failed payout must propagate (credit unchanged).
        assertTrue(!ok && c.credit(address(attacker)) == amount);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

