pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        amount = bound(amount, 1, 1e30);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        uint256 balBefore = address(c).balance;
        assertEq(balBefore, amount);

        // withdrawAll pays out to actor, whose receive() reverts.
        // Reference: the require(callResult) makes withdrawAll revert entirely.
        // Mutant: it 'succeeds', zeroes the credit and drains c's balance.
        vm.prank(actor);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        assertTrue(!ok && address(c).balance == balBefore);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

