pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amt, uint256 pad) public {
        amt = bound(amt, 1 ether, 100 ether);
        pad = bound(pad, 1 ether, 100 ether);

        Attacker attacker = new Attacker(c);

        // padding deposit so the contract holds funds beyond the attacker's credit
        vm.deal(address(this), pad);
        c.deposit{value: pad}();

        // attacker deposits amt then triggers withdrawAll; its receive() re-enters withdrawAll
        vm.deal(address(attacker), amt);
        attacker.attack();

        // General rule: a full withdrawAll removes exactly the caller's credit once;
        // the padding must remain untouched and the caller's credit must be zero.
        assertTrue(address(c).balance == pad && c.credit(address(attacker)) == 0);
    }

    receive() external payable {}
}

contract Attacker {
    C c;
    bool reentered;

    constructor(C _c) { c = _c; }

    function attack() external payable {
        c.deposit{value: address(this).balance}();
        reentered = false;
        c.withdrawAll();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdrawAll();
        }
    }
}

