pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 pad, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);
        pad = bound(pad, amount, 100 ether);

        ReentrancyAttacker atk = new ReentrancyAttacker(c);

        // extra padding so the mutant's double-draw can actually pay out
        vm.deal(address(atk), amount + pad);
        atk.deposit{value: amount}();
        vm.deal(address(c), pad);

        atk.attack();

        // c pays a withdrawing depositor exactly their deposited credit, exactly once
        assertTrue(address(atk).balance == amount);
    }
}

contract ReentrancyAttacker {
    C immutable c;
    constructor(C target) { c = target; }
    function deposit() external payable { c.deposit{value: msg.value}(); }
    function attack() external { c.withdrawAll(); }
    receive() external payable {
        try c.withdrawAll() {} catch {}
    }
}

