pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 padding) public {
        amount = bound(amount, 1, 100 ether);
        padding = bound(padding, 0, amount - 1);
        vm.assume(padding < amount);

        attacker = new Attacker(c);
        vm.deal(address(attacker), amount);
        attacker.deposit(amount);
        attacker.attack();

        // Rule: after a full reentrant withdrawAll attempt, the contract holds
        // exactly the original padding — the payout occurred exactly once and
        // did not revert. The mutant double-draws (underflow) and the whole
        // transaction reverts, leaving padding + amount in the contract.
        assertTrue(address(c).balance == padding, "payout must happen exactly once and succeed");
    }
}

contract Attacker {
    C c;
    constructor(C _c) { c = _c; }
    function deposit(uint256 a) external payable {
        c.deposit{value: a}();
    }
    function attack() external {
        c.withdrawAll();
    }
    receive() external payable {
        // reenter; tolerate revert (blocked in reference)
        (bool s, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector));
        s;
    }
}

