pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address depositor = address(0xA11CE);

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amt, uint256 pad) public {
        bound(amt, 1, 1e30);
        bound(pad, amt, 1e36);

        // extra padding so the mutant's double-draw does not underflow/revert
        vm.deal(address(this), pad);
        c.deposit{value: pad}();

        // depositor funds their credit
        vm.deal(depositor, amt);
        vm.prank(depositor);
        c.deposit{value: amt}();

        // re-entrant attacker receives the payout and calls back once
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), 0);
        attacker.setCredit(depositor);
        vm.prank(depositor);
        c.withdrawAll();

        // In P the lock blocks the reentrant draw exactly once: balance stays at pad.
        // In M the reentrant call drains a second time: balance becomes pad - amt.
        assertTrue(address(c).balance == pad);
    }

    receive() external payable {}
}

contract ReentrantAttacker {
    C public target;
    address public who;
    bool public fired;

    constructor(C t) { target = t; }

    function setCredit(address w) external { who = w; }

    receive() external payable {
        if (!fired) {
            fired = true;
            vmTryWithdraw();
        }
    }

    function vmTryWithdraw() internal {
        // re-enter; success/failure is intentionally ignored by the attacker
        (bool ok, ) = address(target).call(abi.encodeWithSignature("withdrawAll()"));
        ok;
    }
}

