pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, bool extraNoise) public {
        amount = bound(amount, 1 wei, 100 ether);
        Attacker attacker = new Attacker();
        if (extraNoise) {
            c.deposit{value: 0}();
        }
        vm.deal(address(attacker), amount);
        attacker.deposit(c, amount);
        assertEq(address(c).balance, amount);

        bool ok;
        try attacker.withdrawAll(c) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: a depositor's withdrawal always succeeds and their credit is zero afterward.
        assertTrue(ok && c.credit(address(attacker)) == 0);
    }
}

contract Attacker {
    function deposit(C c, uint256 amount) external payable {
        c.deposit{value: amount}();
    }

    function withdrawAll(C c) external {
        c.withdrawAll();
    }

    // Re-entrant observer: revert if our credit is still nonzero during the external call.
    receive() external payable {
        if (c_credit(msg.sender) != 0) revert();
    }

    function c_credit(address a) internal view returns (uint256) {
        // credit getter on the C this attacker is interacting with
        return C(msg.sender).credit(a);
    }
}

