pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(attacker));
        amount = bound(amount, 1, 1 ether);

        // victim depositor funds sit in C
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // adversarial re-entrant counterparty withdraws; during its own external
        // call it re-enters withdrawAll
        vm.deal(address(attacker), amount);
        bool ok;
        (ok, ) = address(attacker).call(abi.encodeWithSignature("go()"));
        require(ok, "attacker reverted");

        // General rule: once all credit is withdrawn, C holds zero balance.
        // Reference: re-entrancy also drains the victim's funds, leaving 0.
        // Mutant: re-entrant call sees credit already zeroed, only the attacker's
        // own deposit is paid out, and the victim's amount remains -> fails.
        assertTrue(address(c).balance == 0);
    }
}

contract Attacker {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function go() external {
        c.deposit{value: address(this).balance}();
        c.withdrawAll();
    }

    receive() external payable {
        // re-enter only if there are still enough funds to cover a full credit
        if (address(c).balance >= msg.value) {
            c.withdrawAll();
        }
    }
}
